import{_ as t,o,c as a,a3 as n}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Documentation site","description":"","frontmatter":{"navigation":{"category":"Getting started"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/documentation-site.md"},"headers":[],"relativePath":"guides/documentation-site.md","filePath":"docs/documentation-site.md","lastUpdated":1791373710000}'),s={name:"guides/documentation-site.md"};function i(d,e,c,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h1><p>The VitePress site combines the hand-written guides in <code>docs/</code>, component READMEs, component-level guides, and generated API references. Navigation groups pages by category metadata stored with their docs. Names and descriptions come from package manifests, action metadata, and guide introductions. On phones, the same sections open as compact accordions in the navigation screen.</p><h2 id="add-a-component-guide" tabindex="-1">Add a component guide <a class="header-anchor" href="#add-a-component-guide" aria-label="Permalink to &quot;Add a component guide&quot;">​</a></h2><p>Create Markdown files under the component&#39;s <code>docs/</code> folder. For example, a plugin can have an <code>index.md</code> plus additional pages such as <code>configuration.md</code>; tools and actions use the same layout. The site discovers each file and adds it to that component&#39;s sidebar and reference links. Relative links are checked by <code>pnpm check</code>.</p><p>For component-specific documentation settings, add a <code>docs.yml</code> file at the component root, next to its <code>docs/</code> folder. Put navigation settings under <code>navigation</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">navigation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Compatibility</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artwork/plugin-mark.svg</span></span></code></pre></div><p><code>category</code> is optional; without it, the item appears in its menu&#39;s general group. <code>type</code> is optional and defaults to a regular link. Use <code>card</code> for a self-contained card or <code>spotlight</code> for a wide editorial row. The <code>navigation</code> namespace keeps menu settings separate from other documentation settings that may be added later. An icon path is relative to the component root, alongside <code>docs.yml</code>. Without an explicit <code>icon</code>, the site automatically uses <code>icon.svg</code>, <code>icon.png</code>, <code>icon.webp</code>, <code>logo.svg</code>, <code>logo.png</code>, or <code>logo.webp</code> from the component root when present, falling back to its <code>docs/</code> folder. Discovered icons are included in the built site automatically and appear beside the title on the component&#39;s landing page as well as in navigation. Items without artwork keep the same alignment.</p><p>Add a category to a hand-written guide&#39;s frontmatter with <code>navigation.category</code>; <code>navigation.type</code> can also select <code>card</code> or <code>spotlight</code>. These categories are editorial labels and belong beside their docs, not in a second list in the site configuration.</p><p>To feature a component in the desktop Plugins menu, add <code>navigation.featured: true</code> to the frontmatter of its <code>docs/index.md</code>. It also remains a regular link in its category. A featured item defaults to the card treatment, and can use <code>navigation.type: spotlight</code> to show as a wide row instead. The title and description still come from the page heading and package manifest.</p><p>The component README is the overview when no custom <code>docs/index.md</code> exists. If a custom index exists, it becomes the component landing page and the README remains available as a separate <strong>README</strong> entry.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>The <strong>Reference</strong> section brings together documented exports from plugin and tool source, action inputs and outputs from each <code>action.yml</code>, and exported repository script helpers. TypeDoc follows the source folders discovered from package manifests; action contracts come directly from the action metadata. Add JSDoc beside exported code and add action documentation to <code>action.yml</code> so the site stays in sync without a second list of names or settings.</p><p>TypeDoc reads whole source trees, including implementation modules, so <code>excludeNotDocumented</code> keeps symbols without JSDoc out of the reference. It is a presentation filter, not a completeness check; the JSDoc lint enforces descriptions on exported TypeScript APIs.</p><p>Generated Pumpkin and WASI bindings can appear by name in public signatures, but their generated declarations are not included as reference pages. The docs pipeline generates the needed bindings before TypeDoc runs. Generated pages are build output and ignored by Git; edit source comments, action metadata, or <code>typedoc.json</code> instead.</p><p>VitePress adds an <strong>Edit this page on GitHub</strong> link to Markdown pages. Generated API pages link that action to the corresponding source file where TypeDoc can identify one.</p><p>The site shows <strong>Last updated</strong> using Git history. The docs workflow fetches full history so pages that were not changed in the latest commit still show their latest edit time.</p><h2 id="llms-txt" tabindex="-1">llms.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to &quot;llms.txt&quot;">​</a></h2><p>The site generates <code>/llms.txt</code> during the VitePress build from discovered guide pages, component documentation, package and action metadata, and API references. Guide and component links point to raw Markdown in the repository; generated API links point to the public docs site. The generated build-side copy is gitignored and stored under <code>docs/</code>. Update source docs or metadata to change its entries; update the generator in <code>docs/.vitepress/config.mts</code> to change its structure. The shared page head links to the file with <code>rel=&quot;describedby&quot;</code>, and the development server serves the same generated content at <code>/llms.txt</code>.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>The site uses Pumpkin&#39;s <code>#FF7518</code> accent. Light-mode text uses a darker orange for contrast; buttons, owner labels, and the home-page title use the primary color. Dark mode uses the primary orange for links, with a lighter hover shade.</p><h2 id="contributors-and-versions" tabindex="-1">Contributors and versions <a class="header-anchor" href="#contributors-and-versions" aria-label="Permalink to &quot;Contributors and versions&quot;">​</a></h2><p>The <a href="/pumpkin-plugins/team">Team page</a> lives at <code>/team</code>, with its own header link, and uses VitePress&#39;s native team components. Its data loader fetches all pages of the repository&#39;s GitHub contributor list during site builds and development, excluding accounts marked as bots and common automation accounts. Full names come from public GitHub profiles, falling back to usernames when no name is set. Avatars and profile links also come from GitHub; there is no contributor list to maintain. Each card shows GitHub&#39;s repository contribution count. <code>filiphsps</code> is explicitly marked as the owner and always sorted first; other contributors are sorted by contribution count. GitHub may take time to refresh contributor statistics. The lookup requires network access and fails the build if GitHub is unavailable. Set <code>GITHUB_TOKEN</code> locally if unauthenticated requests are rate limited; the docs workflow supplies its read-only token. Only the contributor cards are included in the published site, not the loader or token.</p><p>Plugin and action landing pages, READMEs, and API overview pages show native VitePress version badges. Versions come from each plugin&#39;s package manifest or the action&#39;s version file. Badges link to the matching release when its tag exists in the checkout; unreleased versions remain linkless. Tag names come from the release configuration, and the workflow&#39;s full checkout includes the tags.</p><h2 id="local-commands" tabindex="-1">Local commands <a class="header-anchor" href="#local-commands" aria-label="Permalink to &quot;Local commands&quot;">​</a></h2><p>Run <code>pnpm run docs</code> to generate bindings and the API reference, then build the complete static site. The two independent binding-generation steps run concurrently; TypeDoc and VitePress then run in order because the site reads the generated API pages. Use <code>pnpm run dev:docs</code> to generate the same inputs and start the VitePress development server, or <code>pnpm run docs:preview</code> to preview the last built site.</p><p>The pipeline can also be run in stages: <code>pnpm run docs:types</code> generates the binding declarations, <code>pnpm run docs:api</code> generates the TypeDoc reference after the bindings, and <code>pnpm run docs:site</code> builds the VitePress site from those generated pages. The binding steps can be run individually with <code>pnpm run docs:types:plugin-kit</code> or <code>pnpm run docs:types:update-check</code>. Plugin guest declarations can be generated with <code>pnpm run docs:types:plugins</code>. <code>pnpm run docs:build</code> is an alias for the complete production build.</p><p>The separate <code>.github/workflows/docs.yml</code> workflow checks docs on pull requests and publishes the site from pushes to <code>master</code> or <code>main</code>. It deploys a GitHub Pages artifact and mirrors the built files to the <code>gh-pages</code> branch. Configure the repository&#39;s Pages source to <strong>GitHub Actions</strong>.</p>`,27)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
